(*森峰-余云安需求：支撑气缸根据零件避让下落，具备夹持中的功能，但是运行过程中不动作，不执行避让*)
R_SupCylUp1(CLK :=(g_bSupCyl2Up1 OR bSupCylUp1));      (*支撑气缸1上升*)
R_SupCylDown1(CLK :=(g_bSupCyl2Down1 OR bSupCylDown1));  (*支撑气缸1下降*)

(*------------------------------命令输出部分---------------------------*)
(*1、命令输出有到位信号，先等到位信号，在使用延时时间，没到位信号，只使用延时时间*)
(*2、学BC，也不使用界面反馈信号灯了，只管输出*)
(*3 是否加入滤波，对硬件的输入信号，进行滤波*)
IF R_SupCylUp1.Q THEN
  IF g_boSupCyl2Up1 AND g_boSupCyl2Down1=FALSE THEN(*如果已经输出完成了，就不发送输出命令了*)
    DelayTon1(IN :=FALSE);
    M.ENABLE[267] := 0;
    g_bExecuteFinishedM267 := FALSE;
    g_bFinishedM267_1 := FALSE;
    g_boSupCyl2Up_Done1 := TRUE;  
    g_boSupCyl2Down_Done1 := FALSE;
  ELSE
    IF g_bUseSup2Cyl1 THEN(*使用了这个气缸*)
      g_noSupCyl2Switch1 := 10;
      (*重置输出完成信号*)
      g_boSupCyl2Up_Done1 := FALSE;  
      g_boSupCyl2Down_Done1 := FALSE;
    ELSE(*未使用这个气缸，则直接给完成信号*)
      g_noSupCyl2Switch1 := 0;
      M.ENABLE[267] := 0;
      g_bExecuteFinishedM267 := FALSE;
      g_bFinishedM267_1 := FALSE;
      g_boSupCyl2Up_Done1 := TRUE;  
      g_boSupCyl2Down_Done1 := FALSE;
    END_IF;
  END_IF;
  IF g_fSup2Cy1InYCoor1-g_fCurrentCoordYBuffer < g_fSup2CylDownDis1 AND g_biAxIsYisHome AND g_bSenF_SupportIsAvoid1 THEN
     g_noSupCyl2Switch1 := 0;
     M.ENABLE[267] := 0;
     g_bExecuteFinishedM267 := FALSE;
     g_bFinishedM267_1 := FALSE;
     g_boSupCyl2Up_Done1 := TRUE;  
     g_boSupCyl2Down_Done1 := TRUE;
  END_IF;  
  DelayTon1(IN :=FALSE);
  bSupCylUp1 := FALSE;  
  g_bSupCyl2Up1 := FALSE;
  DelayTon_Down1(IN := FALSE);
  g_bLoadSupportCyl1DownNoSignalAlarm := FALSE;
  g_nDownCmdCount1 := 0;
END_IF; 

IF R_SupCylDown1.Q THEN
  IF g_boSupCyl2Up1=FALSE AND g_boSupCyl2Down1 THEN(*如果已经输出完成了，就不发送输出命令了*)
    DelayTon1(IN :=FALSE);
    M.ENABLE[267] := 0;
    g_bExecuteFinishedM267 := FALSE;
    g_bFinishedM267_1 := FALSE;
    g_boSupCyl2Up_Done1 := FALSE;  
    g_boSupCyl2Down_Done1 := TRUE; 
  ELSE
    IF g_bUseSup2Cyl1 THEN(*使用了这个气缸*)
      g_noSupCyl2Switch1 := 50;
        (*重置输出完成信号*)
      g_boSupCyl2Up_Done1 := FALSE;  
      g_boSupCyl2Down_Done1 := FALSE;  
    ELSE(*未使用这个气缸，则直接给完成信号*)
      g_noSupCyl2Switch1 := 0;
      M.ENABLE[267] := 0;
      g_bExecuteFinishedM267 := FALSE;
      g_bFinishedM267_1 := FALSE;
      g_boSupCyl2Up_Done1 := FALSE;  
      g_boSupCyl2Down_Done1 := TRUE;  
    END_IF;
  END_IF;
  DelayTon1(IN :=FALSE);
  bSupCylDown1 := FALSE;  
  g_bSupCyl2Down1 := FALSE;
  bLoadSupportCyl1UpNoSignalAlarm := FALSE;
END_IF; 

CASE g_noSupCyl2Switch1 OF
  0:
   g_noSupCyl2Switch1 := 0;
  10:(*上升命令输出*)
    g_boSupCyl2Up1 := TRUE;
    g_boSupCyl2Down1 := FALSE;
    DelayTon_Down1(IN := FALSE);
    g_bLoadSupportCyl1DownNoSignalAlarm := FALSE;
    DelayTon_Up1(IN := FALSE);
    fDelayTime1 := g_fSupCyl2Up_DelayTime1;
    IF g_bSupCyl2Up_UseINPOS1 THEN(*使用到位信号*)
      g_noSupCyl2Switch1 := 20;
    ELSE(*使用延时信号*)
      g_noSupCyl2Switch1 := 30;
    END_IF;
  20:(*等待到位信号*)
    IF g_bSupCyl2Up_INPOS1 THEN
      g_boSupCyl2Up_Done1 := TRUE;
      g_nSupCyl2CMD1 := 1;
      g_noSupCyl2Switch1 := 0;
      M.ENABLE[267] := 0;
      g_bExecuteFinishedM267 := FALSE;
      g_bFinishedM267_1 := FALSE;
      g_bUseSup2CylState1 := TRUE;
      bCYl1UpState := TRUE;
      bLoadSupportCyl1UpNoSignalAlarm := FALSE;
      DelayTon_Up1(IN := FALSE);
    ELSE
      IF NOT bCYl1UpState THEN
        DelayTon_Up1(IN := TRUE,PT := LREAL_TO_TIME(g_fSupCyl2Up_DelayTime1/1000.0));
        IF DelayTon_Up1.Q THEN
           DelayTon_Up1(IN := FALSE);
           bLoadSupportCyl1UpNoSignalAlarm := TRUE;
        END_IF;
      END_IF;
    END_IF;
  30:(*延时并输出完成信号*)
    DelayTon1(IN :=TRUE,PT := LREAL_TO_TIME(fDelayTime1/1000.0));
    IF DelayTon1.Q THEN
      g_boSupCyl2Up_Done1 := TRUE;
      g_nSupCyl2CMD1 := 1;
      DelayTon1(IN :=FALSE);
      g_noSupCyl2Switch1 := 0;
      M.ENABLE[267] := 0;
      g_bExecuteFinishedM267 := FALSE;
      g_bFinishedM267_1 := FALSE;
      g_bUseSup2CylState1 := TRUE;
      bCYl1UpState := TRUE;
    END_IF;

  50:(*下降命令输出*)
    g_boSupCyl2Up1 := FALSE;
    g_boSupCyl2Down1 := TRUE;
    bLoadSupportCyl1UpNoSignalAlarm := FALSE;
    DelayTon_Up1(IN := FALSE);
    fDelayTime1 := g_fSupCyl2Down_DelayTime1;
    IF g_bSupCyl2Down_UseINPOS1 THEN(*使用到位信号*)
      g_noSupCyl2Switch1 := 60;
    ELSE(*使用延时信号*)
      g_noSupCyl2Switch1 := 70;
    END_IF;
  60: (*等待到位信号*)
    IF g_bSupCyl2Down_INPOS1 THEN
      g_boSupCyl2Down_Done1 := TRUE;
      g_nSupCyl2CMD1 := -1;
      g_noSupCyl2Switch1 := 0;
      M.ENABLE[267] := 0;
      g_bExecuteFinishedM267 := FALSE;
      g_bFinishedM267_1 := FALSE;
      g_bUseSup2CylState1 := FALSE;
      DelayTon_Down1(IN := FALSE);
      g_bLoadSupportCyl1DownNoSignalAlarm := FALSE;
      bCYl1UpState := FALSE;
    ELSE
      IF bCYl1UpState THEN
        DelayTon_Down1(IN := TRUE,PT := LREAL_TO_TIME(g_fSupCyl2Down_DelayTime1/1000.0));
        IF DelayTon_Down1.Q THEN
           DelayTon_Down1(IN := FALSE);
           g_bLoadSupportCyl1DownNoSignalAlarm := TRUE;
        END_IF;
      END_IF;
    END_IF;
  70:(*延时并输出完成信号*)
    DelayTon1(IN :=TRUE,PT := LREAL_TO_TIME(fDelayTime1/1000.0));
    IF DelayTon1.Q THEN
      g_boSupCyl2Down_Done1 := TRUE;
      g_nSupCyl2CMD1 := -1;
      DelayTon1(IN :=FALSE);
      g_noSupCyl2Switch1 := 0;
      M.ENABLE[267] := 0;
      g_bExecuteFinishedM267 := FALSE;
      g_bFinishedM267_1 := FALSE;
      g_bUseSup2CylState1 := FALSE;
      bCYl1UpState := FALSE;
    END_IF;
END_CASE;


(*新加的气缸状态切换,气缸到位超时报警和目前默认到位时间用的一个时间*)
SupCyl1State(
  bUseUpSignal := g_bSupCyl2Up_UseINPOS1,
  bUseDownSignal := g_bSupCyl2Down_UseINPOS1,
  boCylUp := g_boSupCyl2Up1,
  boCylDown := g_boSupCyl2Down1,
  bUpInplace := g_bSupCyl2Up_INPOS1,
  bDownInplace := g_bSupCyl2Down_INPOS1,
  bUpInplaceNoFilter := bCyl1UpSignalNoFilter,
  bDownInplaceNoFilter := bCyl1DownSignalNoFilter,
  bArrayConfigOutputUp := ArrayConfigOutputNumber[124],
  bArrayConfigOutputDown := ArrayConfigOutputNumber[127],
  dClylinderUpDelayTime := LREAL_TO_DINT(g_fSupCyl2Up_DelayTime1),
  dClylinderDownDelayTime := LREAL_TO_DINT(g_fSupCyl2Down_DelayTime1),
  dClylinderUpOverDelayTime := LREAL_TO_DINT(g_fSupCyl2Up_DelayTime1),
  dClylinderDownOverDelayTime := LREAL_TO_DINT(g_fSupCyl2Down_DelayTime1),
  bCylState  => bCYl1UpState,
  bCylStateToHMI => g_bUseSup2CylState1,
  bCylUpNoSignalAlarm => bLoadSupportCyl1UpNoSignalAlarm,
  bCylDownNoSignalAlarm => g_bLoadSupportCyl1DownNoSignalAlarm,
  bArrayConfigOutputUp_FB => ArrayConfigOutputNumber[124],
  bArrayConfigOutputDown_FB => ArrayConfigOutputNumber[127]
);

R_SupCylUp2(CLK :=(g_bSupCyl2Up2 OR bSupCylUp2));      (*支撑气缸2上升*)
R_SupCylDown2(CLK :=(g_bSupCyl2Down2 OR bSupCylDown2));  (*支撑气缸2下降*)

IF R_SupCylUp2.Q THEN
  IF g_boSupCyl2Up2 AND g_boSupCyl2Down2=FALSE THEN(*如果已经输出完成了，就不发送输出命令了*)
    DelayTon2(IN :=FALSE);
    M.ENABLE[267] := 0;
    g_bExecuteFinishedM267 := FALSE;
    g_bFinishedM267_2 := FALSE;
    g_boSupCyl2Up_Done2 := TRUE;  
    g_boSupCyl2Down_Done2 := FALSE;
  ELSE
    IF g_bUseSup2Cyl2 THEN(*使用了这个气缸*)
      g_noSupCyl2Switch2 := 10;
        (*重置输出完成信号*)
      g_boSupCyl2Up_Done2 := FALSE;  
      g_boSupCyl2Down_Done2 := FALSE;
    ELSE(*未使用这个气缸，则直接给完成信号*)
      g_noSupCyl2Switch2 := 0;
      M.ENABLE[267] := 0;
      g_bExecuteFinishedM267 := FALSE;
      g_bFinishedM267_2 := FALSE;
      g_boSupCyl2Up_Done2 := TRUE;  
      g_boSupCyl2Down_Done2 := FALSE;
    END_IF;
  END_IF;

  IF g_fSup2Cy1InYCoor2-g_fCurrentCoordYBuffer < g_fSup2CylDownDis2 AND g_biAxIsYisHome AND g_bSenF_SupportIsAvoid2 THEN
    DelayTon2(IN :=FALSE);
    M.ENABLE[267] := 0;
    g_bExecuteFinishedM267 := FALSE;
    g_bFinishedM267_2 := FALSE;
    g_boSupCyl2Up_Done2 := TRUE;  
    g_boSupCyl2Down_Done2 := TRUE;
    g_noSupCyl2Switch2 := 0;
  END_IF;  

  DelayTon2(IN :=FALSE);
  bSupCylUp2 := FALSE;  
  g_bSupCyl2Up2 := FALSE;
  DelayTon_Down2(IN := FALSE);
  g_bLoadSupportCyl2DownNoSignalAlarm := FALSE;
  g_nDownCmdCount2 := 0;
END_IF; 

IF R_SupCylDown2.Q THEN
  IF g_boSupCyl2Up2=FALSE AND g_boSupCyl2Down2 THEN(*如果已经输出完成了，就不发送输出命令了*)
    DelayTon2(IN :=FALSE);
    M.ENABLE[267] := 0;
    g_bExecuteFinishedM267 := FALSE;
    g_bFinishedM267_2 := FALSE;
    g_boSupCyl2Up_Done2 := FALSE;  
    g_boSupCyl2Down_Done2 := TRUE;
  ELSE
    IF g_bUseSup2Cyl2 THEN(*使用了这个气缸*)
      g_noSupCyl2Switch2 := 50;
        (*重置输出完成信号*)
      g_boSupCyl2Up_Done2 := FALSE;  
      g_boSupCyl2Down_Done2 := FALSE;
    ELSE(*未使用这个气缸，则直接给完成信号*)
      g_noSupCyl2Switch2 := 0;
      M.ENABLE[267] := 0;
      g_bExecuteFinishedM267 := FALSE;
      g_bFinishedM267_2 := FALSE;
      g_boSupCyl2Up_Done2 := FALSE;  
      g_boSupCyl2Down_Done2 := TRUE;
    END_IF;
  END_IF;

  DelayTon2(IN :=FALSE);
  bSupCylDown2 := FALSE;  
  g_bSupCyl2Down2 := FALSE;
  bLoadSupportCyl2UpNoSignalAlarm := FALSE;
END_IF; 

CASE g_noSupCyl2Switch2 OF
  0:
   g_noSupCyl2Switch2 := 0;
  10:(*上升命令输出*)
    g_boSupCyl2Up2 := TRUE;
    g_boSupCyl2Down2 := FALSE;
     DelayTon_Down2(IN := FALSE);
