           g_bLoadSupportCyl2DownNoSignalAlarm := TRUE;
        END_IF;
      END_IF;
    END_IF;
  70:(*延时并输出完成信号*)
    DelayTon2(IN :=TRUE,PT := LREAL_TO_TIME(fDelayTime2/1000.0));
    IF DelayTon2.Q THEN
      g_boSupCyl2Down_Done2 := TRUE;
      DelayTon2(IN :=FALSE);
      g_noSupCyl2Switch2 := 0;
      M.ENABLE[267] := 0;
      g_bExecuteFinishedM267 := FALSE;
      g_bFinishedM267_2 := FALSE;
      g_bUseSup2CylState2 := FALSE;
      bCYl2UpState := FALSE;
    END_IF;
END_CASE;


