  END_IF;

  IF g_fSup2Cy1InYCoor3-g_fCurrentCoordYBuffer < g_fSup2CylDownDis3 AND g_biAxIsYisHome AND g_bSenF_SupportIsAvoid3 THEN
      g_noSupCyl2Switch3 := 0;
