    END_IF;
  60: (*等待到位信号*)
    IF g_bSupCyl2Down_INPOS3 THEN
       g_boSupCyl2Down_Done3 := TRUE;
      g_noSupCyl2Switch3 := 0;
      M.ENABLE[267] := 0;
      g_bExecuteFinishedM267 := FALSE;
      g_bFinishedM267_3 := FALSE;
      g_bUseSup2CylState3 := FALSE;
      DelayTon_Down3(IN := FALSE);
      g_bLoadSupportCyl3DownNoSignalAlarm := FALSE;
      bCYl3UpState := FALSE;
    ELSE
      IF bCYl3UpState THEN
        DelayTon_Down3(IN := TRUE,PT := LREAL_TO_TIME(g_fSupCyl2Down_DelayTime3/1000.0));
        IF DelayTon_Down3.Q THEN
          DelayTon_Down3(IN := FALSE);
          g_bLoadSupportCyl3DownNoSignalAlarm := TRUE;
        END_IF;
      END_IF;
    END_IF;
  70:(*延时并输出完成信号*)
    DelayTon3(IN :=TRUE,PT := LREAL_TO_TIME(fDelayTime3/1000.0));
    IF DelayTon3.Q THEN
      g_boSupCyl2Down_Done3 := TRUE;
      DelayTon3(IN :=FALSE);
      g_noSupCyl2Switch3 := 0;
      M.ENABLE[267] := 0;
      g_bExecuteFinishedM267 := FALSE;
      g_bFinishedM267_3 := FALSE;
      g_bUseSup2CylState3 := FALSE;
      bCYl3UpState := FALSE;
    END_IF;
END_CASE;



(*新加的气缸状态切换,气缸到位超时报警和目前默认到位时间用的一个时间*)
SupCyl3State(
  bUseUpSignal := g_bSupCyl2Up_UseINPOS3,
  bUseDownSignal := g_bSupCyl2Down_UseINPOS3,
  boCylUp := g_boSupCyl2Up3,
  boCylDown := g_boSupCyl2Down3,
  bUpInplace := g_bSupCyl2Up_INPOS3,
  bDownInplace := g_bSupCyl2Down_INPOS3,
  bUpInplaceNoFilter := bCyl3UpSignalNoFilter,
  bDownInplaceNoFilter := bCyl3DownSignalNoFilter,
  bArrayConfigOutputUp := ArrayConfigOutputNumber[126],
  bArrayConfigOutputDown := ArrayConfigOutputNumber[129],
  dClylinderUpDelayTime := LREAL_TO_DINT(g_fSupCyl2Up_DelayTime3),
  dClylinderDownDelayTime := LREAL_TO_DINT(g_fSupCyl2Down_DelayTime3),
  dClylinderUpOverDelayTime := LREAL_TO_DINT(g_fSupCyl2Up_DelayTime3),
  dClylinderDownOverDelayTime := LREAL_TO_DINT(g_fSupCyl2Down_DelayTime3),
  bCylState  => bCYl3UpState,
  bCylStateToHMI => g_bUseSup2CylState3,
  bCylUpNoSignalAlarm => bLoadSupportCyl3UpNoSignalAlarm,
  bCylDownNoSignalAlarm => g_bLoadSupportCyl3DownNoSignalAlarm,
  bArrayConfigOutputUp_FB => ArrayConfigOutputNumber[126],
  bArrayConfigOutputDown_FB => ArrayConfigOutputNumber[129]
);


R_SupCylUp4(CLK :=(g_bSupCyl2Up4 OR bSupCylUp4));      (*支撑气缸4上升*)
R_SupCylDown4(CLK :=(g_bSupCyl2Down4 OR bSupCylDown4));  (*支撑气缸4下降*)

IF R_SupCylUp4.Q THEN
  IF g_boSupCyl2Up4 AND g_boSupCyl2Down4=FALSE THEN(*如果已经输出完成了，就不发送输出命令了*)
    DelayTon4(IN :=FALSE);
    M.ENABLE[267] := 0;
    g_bExecuteFinishedM267 := FALSE;
    g_bFinishedM267_4 := FALSE;
    g_boSupCyl2Up_Done4 := TRUE;  
    g_boSupCyl2Down_Done4 := FALSE;
  ELSE
    IF g_bUseSup2Cyl4 THEN(*使用了这个气缸*)
      g_noSupCyl2Switch4 := 10;
        (*重置输出完成信号*)
      g_boSupCyl2Up_Done4 := FALSE;  
      g_boSupCyl2Down_Done4 := FALSE;
    ELSE
      g_noSupCyl2Switch4 := 0;
      M.ENABLE[267] := 0;
      g_bExecuteFinishedM267 := FALSE;
      g_bFinishedM267_4 := FALSE;
      g_boSupCyl2Up_Done4 := TRUE;  
      g_boSupCyl2Down_Done4 := TRUE;
    END_IF;
  END_IF;

  IF g_fSup2Cy1InYCoor4-g_fCurrentCoordYBuffer < g_fSup2CylDownDis4 AND g_biAxIsYisHome AND g_bSenF_SupportIsAvoid4 THEN
      g_noSupCyl2Switch4 := 0;
      M.ENABLE[267] := 0;
      g_bExecuteFinishedM267 := FALSE;
      g_bFinishedM267_4 := FALSE;
      g_boSupCyl2Up_Done4 := TRUE;  
      g_boSupCyl2Down_Done4 := TRUE;
  END_IF;  
  DelayTon4(IN :=FALSE);
  bSupCylUp4 := FALSE;  
  g_bSupCyl2Up4 := FALSE;
  DelayTon_Down4(IN := FALSE);
  g_bLoadSupportCyl4DownNoSignalAlarm := FALSE;
  g_nDownCmdCount4 := 0;
END_IF; 

IF R_SupCylDown4.Q THEN
  IF g_boSupCyl2Up4=FALSE AND g_boSupCyl2Down4 THEN(*如果已经输出完成了，就不发送输出命令了*)
    DelayTon4(IN :=FALSE);
    M.ENABLE[267] := 0;
    g_bExecuteFinishedM267 := FALSE;
    g_bFinishedM267_4 := FALSE;
    g_boSupCyl2Up_Done4 := FALSE;  
    g_boSupCyl2Down_Done4 := TRUE;
  ELSE
    IF g_bUseSup2Cyl4 THEN(*使用了这个气缸*)
      g_noSupCyl2Switch4 := 50;
      (*重置输出完成信号*)
      g_boSupCyl2Up_Done4 := FALSE;  
      g_boSupCyl2Down_Done4 := FALSE;  
    ELSE
      g_noSupCyl2Switch4 := 0;
      M.ENABLE[267] := 0;
      g_bExecuteFinishedM267 := FALSE;
      g_bFinishedM267_4 := FALSE;
      g_boSupCyl2Up_Done4 := FALSE;  
      g_boSupCyl2Down_Done4 := TRUE;  
    END_IF;
  END_IF;
  DelayTon4(IN :=FALSE);
  bSupCylDown4 := FALSE;  
  g_bSupCyl2Down4 := FALSE;
  bLoadSupportCyl4UpNoSignalAlarm := FALSE;
END_IF; 

CASE g_noSupCyl2Switch4 OF
  0:
   g_noSupCyl2Switch4 := 0;
  10:(*上升命令输出*)
    g_boSupCyl2Up4 := TRUE;
    g_boSupCyl2Down4 := FALSE;
     DelayTon_Down4(IN := FALSE);
    g_bLoadSupportCyl4DownNoSignalAlarm := FALSE;
    DelayTon_Up4(IN := FALSE);
    fDelayTime4 := g_fSupCyl2Up_DelayTime4;
    IF g_bSupCyl2Up_UseINPOS4 THEN(*使用到位信号*)
      g_noSupCyl2Switch4 := 20;
    ELSE(*使用延时信号*)
      g_noSupCyl2Switch4 := 30;
    END_IF;
  20:(*等待到位信号*)
    IF g_bSupCyl2Up_INPOS4 THEN
      g_boSupCyl2Up_Done4 := TRUE;
      g_noSupCyl2Switch4 := 0;
      M.ENABLE[267] := 0;
      g_bExecuteFinishedM267 := FALSE;
      g_bFinishedM267_4 := FALSE;
      g_bUseSup2CylState4 := TRUE;
      bCYl4UpState := TRUE;
      bLoadSupportCyl4UpNoSignalAlarm := FALSE;
      DelayTon_Up4(IN := FALSE);
    ELSE
      IF NOT bCYl4UpState THEN
        DelayTon_Up4(IN := TRUE,PT := LREAL_TO_TIME(g_fSupCyl2Up_DelayTime4/1000.0));
        IF DelayTon_Up4.Q THEN
           DelayTon_Up4(IN := FALSE);
           bLoadSupportCyl4UpNoSignalAlarm := TRUE;
        END_IF;
      END_IF;
    END_IF;
  30:(*延时并输出完成信号*)
    DelayTon4(IN :=TRUE,PT := LREAL_TO_TIME(fDelayTime4/1000.0));
    IF DelayTon4.Q THEN
      g_boSupCyl2Up_Done4 := TRUE;
      DelayTon4(IN :=FALSE);
      g_noSupCyl2Switch4 := 0;
      M.ENABLE[267] := 0;
      g_bExecuteFinishedM267 := FALSE;
      g_bFinishedM267_4 := FALSE;
      g_bUseSup2CylState4 := TRUE;
       bCYl4UpState := TRUE;
    END_IF;

  50:(*下降命令输出*)
    g_boSupCyl2Up4 := FALSE;
    g_boSupCyl2Down4 := TRUE;
    bLoadSupportCyl4UpNoSignalAlarm := FALSE;
    DelayTon_Up4(IN := FALSE);
    fDelayTime4 := g_fSupCyl2Down_DelayTime4;
    IF g_bSupCyl2Down_UseINPOS4 THEN(*使用到位信号*)
      g_noSupCyl2Switch4 := 60;
    ELSE(*使用延时信号*)
      g_noSupCyl2Switch4 := 70;
    END_IF;
  60: (*等待到位信号*)
    IF g_bSupCyl2Down_INPOS4 THEN
       g_boSupCyl2Down_Done4 := TRUE;
      g_noSupCyl2Switch4 := 0;
      M.ENABLE[267] := 0;
      g_bExecuteFinishedM267 := FALSE;
      g_bFinishedM267_4 := FALSE;
      g_bUseSup2CylState4 := FALSE;
      DelayTon_Down4(IN := FALSE);
      g_bLoadSupportCyl4DownNoSignalAlarm := FALSE;
      bCYl4UpState := FALSE;
    ELSE
      IF bCYl4UpState THEN
        DelayTon_Down4(IN := TRUE,PT := LREAL_TO_TIME(g_fSupCyl2Down_DelayTime4/1000.0));
        IF DelayTon_Down4.Q THEN
          DelayTon_Down4(IN := FALSE);
          g_bLoadSupportCyl4DownNoSignalAlarm := TRUE;
        END_IF;
      END_IF;
    END_IF;
  70:(*延时并输出完成信号*)
    DelayTon4(IN :=TRUE,PT := LREAL_TO_TIME(fDelayTime4/1000.0));
    IF DelayTon4.Q THEN
      g_boSupCyl2Down_Done4 := TRUE;
      DelayTon4(IN :=FALSE);
      g_noSupCyl2Switch4 := 0;
      M.ENABLE[267] := 0;
      g_bExecuteFinishedM267 := FALSE;
      g_bFinishedM267_4 := FALSE;
      g_bUseSup2CylState4 := FALSE;
      bCYl4UpState := FALSE;
    END_IF;
END_CASE;



(*新加的气缸状态切换,气缸到位超时报警和目前默认到位时间用的一个时间*)
SupCyl4State(
  bUseUpSignal := g_bSupCyl2Up_UseINPOS4,
  bUseDownSignal := g_bSupCyl2Down_UseINPOS4,
  boCylUp := g_boSupCyl2Up4,
  boCylDown := g_boSupCyl2Down4,
