  dClylinderDownDelayTime := LREAL_TO_DINT(g_fSupCyl2Down_DelayTime4),
  dClylinderUpOverDelayTime := LREAL_TO_DINT(g_fSupCyl2Up_DelayTime4),
  dClylinderDownOverDelayTime := LREAL_TO_DINT(g_fSupCyl2Down_DelayTime4),
  bCylState  => bCYl4UpState,
  bCylStateToHMI => g_bUseSup2CylState4,
  bCylUpNoSignalAlarm => bLoadSupportCyl4UpNoSignalAlarm,
  bCylDownNoSignalAlarm => g_bLoadSupportCyl4DownNoSignalAlarm,
  bArrayConfigOutputUp_FB => ArrayConfigOutputNumber[186],
  bArrayConfigOutputDown_FB => ArrayConfigOutputNumber[187]
);


(*添加信号滤波*)
Filter_4(LREAL_TO_TIME(FUN_MSTOS(Cyl1FilterTime)),g_bSupCyl2Up_NONC1,g_biSupCyl2Up_INPOS1,g_bSupCyl2Up_INPOS1);
g_bSupCyl2Up_INPOS1 := FUN_SingalLogic(g_bSupCyl2Up_INPOS1,g_bSupCyl2Up_NONC1);
Filter_1(LREAL_TO_TIME(FUN_MSTOS(Cyl1FilterTime)),g_bSupCyl2Down_NONC1,g_biSupCyl2Down_INPOS1,g_bSupCyl2Down_INPOS1);
g_bSupCyl2Down_INPOS1 := FUN_SingalLogic(g_bSupCyl2Down_INPOS1,g_bSupCyl2Down_NONC1);

bCyl1UpSignalNoFilter := FUN_SingalLogic(g_biSupCyl2Up_INPOS1,g_bSupCyl2Up_NONC1);
bCyl1DownSignalNoFilter := FUN_SingalLogic(g_biSupCyl2Down_INPOS1,g_bSupCyl2Down_NONC1);

Filter_5(LREAL_TO_TIME(FUN_MSTOS(Cyl2FilterTime)),g_bSupCyl2Up_NONC2,g_biSupCyl2Up_INPOS2,g_bSupCyl2Up_INPOS2);
g_bSupCyl2Up_INPOS2 := FUN_SingalLogic(g_bSupCyl2Up_INPOS2,g_bSupCyl2Up_NONC2);
Filter_2(LREAL_TO_TIME(FUN_MSTOS(Cyl2FilterTime)),g_bSupCyl2Down_NONC2,g_biSupCyl2Down_INPOS2,g_bSupCyl2Down_INPOS2);
g_bSupCyl2Down_INPOS2 := FUN_SingalLogic(g_bSupCyl2Down_INPOS2,g_bSupCyl2Down_NONC2);

bCyl2UpSignalNoFilter := FUN_SingalLogic(g_biSupCyl2Up_INPOS2,g_bSupCyl2Up_NONC2);
bCyl2DownSignalNoFilter := FUN_SingalLogic(g_biSupCyl2Down_INPOS2,g_bSupCyl2Down_NONC2);

Filter_6(LREAL_TO_TIME(FUN_MSTOS(Cyl3FilterTime)),g_bSupCyl2Up_NONC3,g_biSupCyl2Up_INPOS3,g_bSupCyl2Up_INPOS3);
g_bSupCyl2Up_INPOS3 := FUN_SingalLogic(g_bSupCyl2Up_INPOS3,g_bSupCyl2Up_NONC3);
Filter_3(LREAL_TO_TIME(FUN_MSTOS(Cyl3FilterTime)),g_bSupCyl2Down_NONC3,g_biSupCyl2Down_INPOS3,g_bSupCyl2Down_INPOS3);
g_bSupCyl2Down_INPOS3 := FUN_SingalLogic(g_bSupCyl2Down_INPOS3,g_bSupCyl2Down_NONC3);

bCyl3UpSignalNoFilter := FUN_SingalLogic(g_biSupCyl2Up_INPOS3,g_bSupCyl2Up_NONC3);
bCyl3DownSignalNoFilter := FUN_SingalLogic(g_biSupCyl2Down_INPOS3,g_bSupCyl2Down_NONC3);


Filter_7(LREAL_TO_TIME(FUN_MSTOS(Cyl4FilterTime)),g_bSupCyl2Up_NONC4,g_biSupCyl2Up_INPOS4,g_bSupCyl2Up_INPOS4);
g_bSupCyl2Up_INPOS4 := FUN_SingalLogic(g_bSupCyl2Up_INPOS4,g_bSupCyl2Up_NONC4);
Filter_8(LREAL_TO_TIME(FUN_MSTOS(Cyl4FilterTime)),g_bSupCyl2Down_NONC4,g_biSupCyl2Down_INPOS4,g_bSupCyl2Down_INPOS4);
g_bSupCyl2Down_INPOS4 := FUN_SingalLogic(g_bSupCyl2Down_INPOS4,g_bSupCyl2Down_NONC4);

bCyl4UpSignalNoFilter := FUN_SingalLogic(g_biSupCyl2Up_INPOS4,g_bSupCyl2Up_NONC4);
bCyl4DownSignalNoFilter := FUN_SingalLogic(g_biSupCyl2Down_INPOS4,g_bSupCyl2Down_NONC4);


(*添加上料支撑气缸报警*)
IF bLoadSupportCyl1UpNoSignalAlarm THEN
  g_Alarm.alarmArray[528] := 1241;
ELSE
   g_Alarm.alarmArray[528] := 0;
END_IF;
IF bLoadSupportCyl2UpNoSignalAlarm THEN
  g_Alarm.alarmArray[529] := 1242;
ELSE
   g_Alarm.alarmArray[529] := 0;
END_IF;
IF bLoadSupportCyl3UpNoSignalAlarm THEN
  g_Alarm.alarmArray[530] := 1243;
ELSE
  g_Alarm.alarmArray[530] := 0;
END_IF;

IF bLoadSupportCyl4UpNoSignalAlarm THEN
  g_Alarm.alarmArray[593] := 1308;
ELSE
